def w3_freeze(admission=None):
    require(isinstance(W3_FROZEN, dict)
            and W3_FROZEN.get("schema") == "pinkha-wave2-exact8f2-runtime-freeze-v1"
            and W3_FROZEN.get("readyForRuntimeAdmission") is True,
            "Wave3 runtime intake is closed: actual exact-source producer/evidence pins are not frozen")
    require(all(isinstance(value, str) and re.fullmatch("[0-9a-f]{64}", value) for value in
                (W3_BUNDLE_SHA, W3_BUILD_ADMISSION_SHA, W3_EXECUTED_PRODUCER_SHA,
                 W3_EXECUTED_DELTA_SHA, W3_STAGE_PLAN_SHA, APP16_STAGE_RECEIPT, APP16_CACHE_QUALIFICATION))
            and type(W3_BUNDLE_BYTES) is int and W3_BUNDLE_BYTES > 0,
            "Actual exact warm-retry receipt pins are pending; a ready profile cannot bypass them")
    require(set(W3_FROZEN) == {"schema", "readyForRuntimeAdmission", "sourceCommit", "sourceTree",
                "canonicalSDKRevision", "sdkReceiptSHA256", "stageReceiptSHA256", "cacheQualificationSHA256", "evidence"}
            and W3_FROZEN["sourceCommit"] == W3_SOURCE and W3_FROZEN["sourceTree"] == W3_TREE
            and W3_FROZEN["canonicalSDKRevision"] == W3_SDK_REVISION,
            "This reviewed intake accepts only the exact warm retry8f2/385 source")
    require(W3_FROZEN["sdkReceiptSHA256"] == SDK_RECEIPT
            and W3_FROZEN["stageReceiptSHA256"] == APP16_STAGE_RECEIPT
            and W3_FROZEN["cacheQualificationSHA256"] == APP16_CACHE_QUALIFICATION,
            "Actual reviewed materialization/stage/cache pins differ")
    expected = W3_FROZEN["evidence"]
    require(isinstance(expected, dict) and set(expected) == W3_EVIDENCE_KEYS
            and expected["sourceRoot"] == W3_SOURCE_ROOT
            and isinstance(expected["app16Producer"], dict) and set(expected["app16Producer"]) == W3_PRODUCER_KEYS,
            "Closed actual producer/evidence profile required")
    if admission is not None:
        require(admission.get("sourceCommit") == W3_SOURCE
                and admission.get("nativeManifestSHA256") == MANIFEST
                and all(admission.get(name) == value for name, value in expected.items())
                and "uiContinuation" not in admission
                and not any(name.endswith("UIOverride") for name in admission),
                "The admission differs from the one frozen source/producer; historical or donor products are not admitted")
    return expected


def w3_ref(reference):
    require(isinstance(reference, dict) and set(reference) == {"path", "sha256", "bytes"},
            "Original common path/SHA256/byte-count pin required")
    return {"path": reference["path"], "sha256": reference["sha256"]}


def w3_module(name, source):
    relative, expected = W3_MODULES[name]
    text = W3_EMBEDDED[name]
    require(sha(text.encode()) == expected and raw(source / relative) == text.encode(),
            "Exact original Wave3 control source changed: " + relative)
    module = _wave3_types.ModuleType("wave2_original_" + name)
    module.__file__ = str(source / relative)
    exec(compile(text, module.__file__, "exec"), module.__dict__)
    return module


def w3_external_module(name, reference):
    """Reviewed staging controls are external to the frozen application tree."""
    expected = W3_EXTERNAL_MODULES[name]
    text = W3_EMBEDDED[name]
    require(sha(text.encode()) == expected and pinned(reference) == text.encode(),
            "Exact reviewed external warm control changed: " + name)
    module = _wave3_types.ModuleType("wave2_original_" + name)
    module.__file__ = reference["path"]
    exec(compile(text, module.__file__, "exec"), module.__dict__)
    return module


def w3_three_stage_inverse(contract, receipt, root_admission, adapter, warm):
    builder, delta_raw = pinned(contract["builder"]), pinned(contract["builderDelta"])
    delta = decode(delta_raw)
    base = W3_EMBEDDED["base_producer"]
    original = W3_EMBEDDED["original_producer"]
    base_delta_raw = W3_EMBEDDED["base_delta"].encode()
    require(sha(base.encode()) == W3_BASE_SHA and sha(original.encode()) == W3_ORIGINAL_SHA
            and sha(base_delta_raw) == W3_BASE_DELTA_SHA, "Original producer inverse inputs changed")
    expected, expected_delta = warm.expand(base, root_admission,
        Path(contract["buildAdmission"]["path"]), contract["buildAdmission"]["sha256"], adapter, W3_ADAPTER_SHA)
    require(builder == expected.encode() and delta == expected_delta
            and delta["schema"] == "pinkha-root-warm-producer-byte-inverse-v1"
            and delta["originalAdapterSHA256"] == W3_ORIGINAL_ADAPTER_SHA
            and sha(builder) == receipt["controllerSHA256"] == delta["candidateSHA256"] == W3_EXECUTED_PRODUCER_SHA
            and sha(delta_raw) == W3_EXECUTED_DELTA_SHA,
            "Actually executed producer is not the exact reviewed root-bound expansion")
    restored = builder.decode()
    for row in reversed(delta["changes"]):
        require(set(row) == {"old", "new", "count"} and restored.count(row["new"]) == row["count"],
                "Wave3 producer inverse occurrence differs")
        restored = restored.replace(row["new"], row["old"])
    require(restored == base, "Wave3 inverse did not restore original9b producer")
    previous = decode(base_delta_raw)
    require(previous["candidateSHA256"] == W3_BASE_SHA and previous["originalSHA256"] == W3_ORIGINAL_SHA
            and previous["inverseRestoresEveryOriginalByte"] is True, "Original9b inverse metadata differs")
    spans = []
    for row in previous["changes"]:
        require(set(row) == {"old", "new", "count", "newPositions"}
                and type(row["count"]) is int and row["count"] > 0
                and len(row["newPositions"]) == row["count"]
                and all(type(value) is int and value >= 0 for value in row["newPositions"])
                and row["newPositions"] == sorted(set(row["newPositions"])), "Original positional inverse differs")
        spans.extend((position, position + len(row["new"]), row["new"], row["old"]) for position in row["newPositions"])
    spans.sort()
    require(all(left[1] <= right[0] for left, right in zip(spans, spans[1:])), "Original inverse spans overlap")
    for start, end, new, old in reversed(spans):
        require(restored[start:end] == new, "Original producer inverse position differs")
        restored = restored[:start] + old + restored[end:]
    require(restored == original, "Three-level inverse lost original617 bytes")
    old, middle, current = map(app16_function_sources, (original.encode(), base.encode(), builder))
    require(all(old[name] == middle[name] == current[name] for name in ("run_phase", "source_state")),
            "Original owned lifecycle or source inventory function changed")
    require(all(old[name] == middle[name] for name in ("verify_runtime_identity", "verify_dependencies")),
            "Original Native/SDK functions were lost before reviewed explicit Wave3 pin substitutions")
    return {"builderSHA256": sha(builder), "deltaSHA256": sha(delta_raw),
            "fullOriginalProducerInverse": True, "originalProducerSHA256": W3_ORIGINAL_SHA,
            "unchangedFunctions": ["run_phase", "source_state"], "originalPositionalSpans": len(spans),
            "warmAdapterSHA256": W3_ADAPTER_SHA, "originalAdapterSHA256": W3_ORIGINAL_ADAPTER_SHA,
            "warmRetryInverseChanges": delta["warmRetryChanges"]}


def w3_failed_preservation(contract, stage, plan, gate, preserve, adapter):
    """Retain the failed result as failure; re-read its preserved full trees."""
    warm = contract["warmRetry"]
    reference = warm["failedPreservation"]
    expected_ref = {"path": W3_FAILED_ROOT + "/failed-preservation1/receipt.json",
                    "sha256": W3_FAILED_PRESERVATION_SHA}
    require(w3_ref(reference) == plan["failedPreservation"] == expected_ref
            and sha(pinned(reference)) == stage["failedPreservationSHA256"] == W3_FAILED_PRESERVATION_SHA,
            "The original failed6aab preservation receipt differs")
    retained = decode(pinned(reference))
    require(retained["schema"] == "pinkha-terminal-failed-build-preservation-v1"
            and retained["status"] == "PASS_FAILED_SOURCE_PRODUCTS_AND_ORIGINAL_EVIDENCE_RETAINED"
            and retained["sourceCommit"] == W3_PREVIOUS
            and retained["sourceTree"] == "69ca9d5d7e602b6f11d309faa9882f829ebc27c1"
            and retained["controllerSHA256"] == W3_FAILED_CONTROL_SHA
            and retained["originalFailure"] == {"exitCode": 65, "uiPhaseRun": False, "applicationAccepted": False}
            and retained["sourceMutated"] is retained["currentProductsMutated"] is retained["cacheMutated"] is False
            and retained["applicationBuilds"] == retained["testsExecuted"] == 0
            and retained["originalEvidence"] == preserve.EXPECTED
            and set(retained["trees"]) == set(preserve.ORIGINALS),
            "The actual terminal failure or complete retention identity differs")
    expected_reverified = {}
    for name, row in retained["trees"].items():
        require(row["original"] == str(preserve.ORIGINALS[name])
                and row["retained"] == str(Path(reference["path"]).parent / name),
                "Failed preservation tree custody differs")
        manifests = {}
        for label in ("before", "retainedManifest", "after"):
            manifest = decode(pinned(row[label]))
            require(manifest["root"] == row["retained" if label == "retainedManifest" else "original"],
                    "Failed retained manifest root differs")
            manifests[label] = manifest["entries"]
        entries = manifests["before"]
        require(entries == manifests["retainedManifest"] == manifests["after"]
                and len(entries) == row["entries"]
                and preserve.inventory(gate.canonical(row["retained"], directory=True)) == entries,
                "Failed retained full bytes, modes, times or links changed: " + name)
        expected_reverified[name] = {"nodes": len(entries), "original": row["original"],
                                    "retained": row["retained"],
                                    "retainedManifestSHA256": row["retainedManifest"]["sha256"]}
    for relative, expected in retained["originalEvidence"].items():
        gate.read_ref({"path": str(Path(W3_FAILED_ROOT) / relative), "sha256": expected})
    reverified_raw = pinned(warm["failedRevalidation"])
    require(sha(reverified_raw) == stage["failedPreservationReverifiedSHA256"]
            and decode(reverified_raw) == {"status": "PASS_FAILED_SOURCE_PRODUCTS_AND_EVIDENCE_REVERIFIED",
                "receiptSHA256": W3_FAILED_PRESERVATION_SHA, "trees": expected_reverified},
            "Actual warm-stage failed retention revalidation differs")

    # This is custody of failed compiler input, never a successful build/test.
    failed = decode(pinned(warm["failedCompilerInputProof"]))
    failed_source = gate.json_ref({"path": W3_FAILED_ROOT + "/build16/source-before.json",
                                  "sha256": preserve.EXPECTED["build16/source-before.json"]})
    failed_admission = gate.json_ref({"path": W3_FAILED_ROOT + "/build-admission.approved.json",
        "sha256": "503ec2057e1d548aaace6672c05b39d520d30271f733741fba3aad7816309646"})
    require(failed["status"] == "OBSERVED_FAILED_APP_COMPILER_INPUTS_NOT_ACCEPTANCE"
            and failed["sourceCommit"] == W3_PREVIOUS and failed["testsExecuted"] == 0
            and failed["originalLogSHA256"] == preserve.EXPECTED["build16/app/original.log"]
            and len(failed["requiredSources"]) == len(failed_admission["selectedNativeTestSources"]) == 43
            and {row["repositoryPath"] for row in failed["requiredSources"]}
                == set(failed_admission["selectedNativeTestSources"]),
            "Retained failed compiler input identity differs")
    for row in failed["requiredSources"]:
        require(row["compiledPath"] == str(Path(W3_SOURCE_ROOT) / row["repositoryPath"])
                and {key: row[key] for key in ("bytes", "sha256")}
                    == failed_source["files"][row["repositoryPath"]],
                "Failed compiler source differs from its original full source observation")
    expected_paths = [row["compiledPath"] for row in failed["requiredSources"]]
    require(failed["actualCompilerFileLists"], "Original failed compiler file list is missing")
    for row in failed["actualCompilerFileLists"]:
        raw_list = gate.read_ref({"path": row["path"], "sha256": row["sha256"]})
        lines = [line.strip().strip('"').casefold() for line in raw_list.decode().splitlines() if line.strip()]
        require(row["requiredSourcePaths"] == expected_paths
                and all(lines.count(path.casefold()) == 1 for path in expected_paths),
                "Retained failed compiler list lost an original source")
        witnesses = adapter.w3_compiler_invocations(Path(W3_FAILED_ROOT) / "build16/app/original.log",
                                                    "AnytypeTests", Path(row["originalPath"]))
        require(row["compilerInvocation"] == witnesses[0] and row["compilerInvocations"] == witnesses,
                "Retained failed compiler list is not tied to its original swiftc invocation")
    return {"failedPreservationSHA256": W3_FAILED_PRESERVATION_SHA,
            "failedPreservationRevalidationSHA256": sha(reverified_raw),
            "failedCompilerInputProofSHA256": warm["failedCompilerInputProof"]["sha256"],
            "priorFailedBuildAccepted": False, "retainedFailedTrees": expected_reverified}


def w3_stage_control_references(plan, contract, gate):
    """Bind the actual six-control d22 plan without a generic extra-key allowance."""
    controls = plan["controls"]
    require(set(controls) == {"originalStager", "originalAdapter", "originalProducer",
                              "preservation", "warmAdapter", "warmStager"},
            "Exactly the six reviewed original and warm controls are required")
    for name, expected in (("originalStager", W3_ORIGINAL_STAGE_SHA), ("originalAdapter", W3_ORIGINAL_ADAPTER_SHA),
                           ("originalProducer", W3_BASE_SHA), ("preservation", W3_FAILED_CONTROL_SHA),
                           ("warmAdapter", W3_ADAPTER_SHA), ("warmStager", W3_STAGE_SHA)):
        require(controls[name]["sha256"] == expected and sha(gate.read_ref(controls[name])) == expected,
                "An original staging control changed: " + name)
    require(gate.read_ref(controls["originalProducer"]) == W3_EMBEDDED["base_producer"].encode(),
            "The actual staged original producer differs from the exact embedded204f base")
    warm_refs = contract["warmRetry"]["controls"]
    require(controls["preservation"] == w3_ref(warm_refs["preservation"])
            and controls["warmAdapter"] == w3_ref(warm_refs["adapter"])
            and controls["warmStager"] == w3_ref(contract["stagingScript"]),
            "The consumer's exact warm control references differ from the actual staged files")
    bundle = plan["gitBundle"]
    require(set(bundle) == {"path", "sha256", "bytes", "prerequisite"}
            and bundle["sha256"] == W3_BUNDLE_SHA and bundle["bytes"] == W3_BUNDLE_BYTES
            and bundle["prerequisite"] == W3_PREVIOUS,
            "The exact transferred8f2 bundle identity, byte count or prerequisite differs")
    # Preserve the original receipt gate's strict two-key reference schema.
    require(len(gate.read_ref({"path": bundle["path"], "sha256": bundle["sha256"]})) == W3_BUNDLE_BYTES,
            "Actual transferred8f2 bundle byte count differs")


def w3_resource512_delta(before, after, prefix=""):
    """Exact JSON leaf delta, with arrays retained as original whole values."""
    if isinstance(before, dict) and isinstance(after, dict):
        result = []
        for key in sorted(set(before) | set(after)):
            if key not in before or key not in after:
                result.append({"path": prefix + "/" + key, "before": before.get(key), "after": after.get(key)})
            else:
                result.extend(w3_resource512_delta(before[key], after[key], prefix + "/" + key))
        return result
    return [] if type(before) is type(after) and before == after else [
        {"path": prefix, "before": before, "after": after}]


def w3_resource512_restore_admission(root_admission, contract, adapter, warm):
    """Qualify one exact resource successor; this is never build approval.

    The proposed-ready preview is historical preparation. Actual approval and
    successful App/UI products remain separately required by w3_freeze and the
    original common producer/phase/compiler gates.
    """
    data = {name: pinned(reference) for name, reference in W3_RESOURCE512_EVIDENCE.items()}
    proposal = decode(data["proposed-admission.preview.txt"])
    disabled = decode(data["build-admission.ready-false.json"])
    report = decode(data["receipt.json"])
    delta = decode(data["exact-resource-only-delta.json"])
    cache = decode(data["cache-requalification.json"])
    policy = decode(data["resource-reassessment.json"])
    require(proposal == root_admission and proposal["readyForBuild"] is True
            and disabled == dict(proposal, readyForBuild=False)
            and contract["cacheQualification"] == W3_RESOURCE512_EVIDENCE["cache-requalification.json"],
            "The final admission is not the exact reviewed original512 resource proposal")
    require(report["schema"] == "pinkha-resource-only-warm-requalification-preview-v1"
            and report["status"] == "PASS_READONLY_RESOURCE_SUCCESSOR_PREPARED_NOT_ADMITTED_NOT_BUILT"
            and report["applicationBuilds"] == report["testsExecuted"] == 0
            and report["effectiveBuildApprovalCreated"] is False
            and report["sourceCacheProductsMutated"] is False
            and report["allSelectedSourceRowsVerified"] == 52
            and report["originalsBefore"] == report["originalsAfter"],
            "Original resource review must remain a read-only, nonexecuting observation")
    for reference in report["originalsBefore"]:
        pinned(reference)
    require(report["sourceBefore"] == report["sourceAfter"]
            and all(report["sourceBefore"][key]["exitCode"] == 0 for key in ("head", "tree", "status"))
            and report["sourceBefore"]["head"]["stdout"].strip() == W3_SOURCE
            and report["sourceBefore"]["tree"]["stdout"].strip() == W3_TREE
            and report["sourceBefore"]["status"]["stdout"] == "",
            "Resource-only preparation changed the frozen clean source")
    refs = W3_RESOURCE512_EVIDENCE
    for key, name in (("newCacheQualification", "cache-requalification.json"),
                      ("resourcePolicy", "resource-reassessment.json"),
                      ("resourceBefore", "resource-before.json"), ("resourceAfter", "resource-after.json"),
                      ("proposedApprovedPreview", "proposed-admission.preview.txt"),
                      ("readyFalseAdmission", "build-admission.ready-false.json"),
                      ("exactResourceDelta", "exact-resource-only-delta.json"),
                      ("byteInverseProof", "byte-inverse-delta.json"),
                      ("expandedProducerPreview", "expanded-producer.preview.txt"),
                      ("expandedProducerDelta", "expanded-versus-original84f.diff")):
        require(report[key] == refs[name], "Original resource review reference changed: " + key)
    require(policy["schema"] == "pinkha-finite-window-resource-reassessment-v1"
            and policy["sourceCommit"] == W3_SOURCE and policy["preparationOnly"] is True
            and policy["effectiveApproval"] is False
            and policy["originalProducerSHA256"] == W3_BASE_SHA
            and policy["ownAppEstimateBytes"] == 6442450944
            and policy["ownUIEstimateBytes"] == 1073741824
            and policy["liveEmergencyFloorBytes"] == 2147483648
            and policy["originalProducerConcurrentMinimumBytes"]
                == policy["proposedConcurrentAllowanceBytes"] == 536870912
            and policy["priorConcurrentAllowanceBytes"] == 4294967296
            and policy["proposedAppEnvelopeBytes"] == 9126805504
            and policy["proposedUIEnvelopeBytes"] == 3758096384,
            "Only the exact original512 finite resource policy is reviewed")
    require(cache["resourceReassessment"] == refs["resource-reassessment.json"]
            and policy["resourceObservation"] == refs["resource-before.json"],
            "Cache successor lacks its exact historical resource basis")
    old_cache_ref = {"path": "/Users/m1/development/anytype-d-active-20261125/main16-wave3-8f2c11713fb8/cache-requalification1/receipt.json",
                     "sha256": "cf181ce88ac84618868a4c1c9faed69288bcb191599e8015271d629bcd0be00a", "bytes": 23679}
    require(cache["priorCacheQualification"] == w3_ref(old_cache_ref),
            "The original4GiB cache receipt is not retained by the resource successor")
    old_cache = decode(pinned(old_cache_ref))
    old_admission_refs = [ref for ref in report["originalsBefore"]
                          if ref["sha256"] == "cf48a0fa5e5a3acdabff9a9e6df77c6abd9098b1b446af107ebf8c397541c640"]
    require(len(old_admission_refs) == 1, "Exactly one unchanged original warm draft is required")
    old_admission = decode(pinned(old_admission_refs[0]))
    require(old_admission["readyForBuild"] is False, "Original4GiB draft was not closed")
    # Compare only resource deltas against the closed draft; this in-memory
    # readiness normalization never creates or admits an approval document.
    prior_reference_with_same_readiness = dict(old_admission, readyForBuild=True)
    require(w3_resource512_delta(prior_reference_with_same_readiness, proposal) == delta["admission"]
            and {row["path"] for row in delta["admission"]}
                == {"/cacheQualification/path", "/cacheQualification/sha256", "/notes", "/warmRetry/concurrentGrowthAllowanceBytes"}
            and w3_resource512_delta(old_cache, cache) == delta["cache"]
            and {row["path"] for row in delta["cache"]}
                == {"/concurrentGrowthAllowanceBytes", "/freeBytes", "/observedAt", "/priorCacheQualification", "/resourceReassessment"}
            and delta["allControlsUnchanged"] is True
            and delta["originalSourceStagingPlanSHA256"] == W3_STAGE_PLAN_SHA,
            "The resource successor contains an unreviewed source, SDK, package, stage, or lifecycle delta")
    require(cache["concurrentGrowthAllowanceBytes"] == proposal["warmRetry"]["concurrentGrowthAllowanceBytes"] == 536870912
            and cache["estimateNewAppPhaseBytes"] == 6442450944 and cache["emergencyFloorBytes"] == 2147483648,
            "App/floor estimates must remain intact in the exact512 successor")
    expected, expected_inverse = warm.expand(W3_EMBEDDED["base_producer"], proposal,
        Path(report["futureApprovedAdmissionPath"]), sha(data["proposed-admission.preview.txt"]), adapter, W3_ADAPTER_SHA)
    inverse = decode(data["byte-inverse-delta.json"])
    require(expected.encode() == data["expanded-producer.preview.txt"] and expected_inverse == inverse
            and sha(expected.encode()) == delta["newExpandedProducerSHA256"]
            and inverse["builds"] == inverse["tests"] == 0,
            "Resource-only preview differs from the unchanged reviewed warm expansion")
    restored = proposal.copy()
    restored["warmRetry"] = proposal["warmRetry"].copy()
    restored["cacheQualification"] = prior_reference_with_same_readiness["cacheQualification"]
    restored["notes"] = prior_reference_with_same_readiness["notes"]
    restored["warmRetry"]["concurrentGrowthAllowanceBytes"] = 4294967296
    require(restored == prior_reference_with_same_readiness, "The resource inverse did not restore the original warm admission")
    return restored, {
        "resourceReviewSHA256": sha(data["receipt.json"]), "resourcePolicySHA256": sha(data["resource-reassessment.json"]),
        "priorCacheSHA256": old_cache_ref["sha256"], "currentCacheSHA256": sha(data["cache-requalification.json"]),
        "appEstimateBytes": 6442450944, "emergencyFloorBytes": 2147483648,
        "concurrentAllowanceBytes": 536870912, "exactResourceInverse": True,
        "previewProvidesBuildApproval": False, "previewExecutesBuildsOrTests": False,
        "freshAllHostCensusAndFiniteWindowRemainRootDispatchPrerequisites": True,
    }


def w3_stage_proof(contract, receipt, root_admission, source, gate, stage_control, adapter, warm, preserve):
    stage_raw, plan_raw = pinned(contract["stagingReceipt"]), pinned(contract["stagingInput"])
    stage, plan = decode(stage_raw), decode(plan_raw)
    warm_refs = contract["warmRetry"]
    require(set(warm_refs) == {"controls", "failedPreservation", "failedRevalidation", "packagesBefore",
                              "packagesAfter", "uiCacheBefore", "failedCompilerInputProof"}
            and set(warm_refs["controls"]) == {"adapter", "preservation"},
            "Closed warm retry preservation, package and compiler custody is required")
    require(sha(pinned(contract["stagingScript"])) == W3_STAGE_SHA == stage["controllerSHA256"]
            and sha(stage_raw) == APP16_STAGE_RECEIPT == receipt["inputs"]["stagingReceiptSHA256"]
            and stage["protocol"] == "pinkha-root-warm-retry-forward-staging-v1"
            and stage["status"] == "PASS_EXACT_APP16_SOURCE_AND_NATIVE_REUSED_ORIGINALS_RETAINED"
            and stage["sourceCommit"] == W3_SOURCE and stage["tree"] == W3_TREE
            and stage["priorSource"] == W3_PREVIOUS and stage["planSHA256"] == sha(plan_raw) == W3_STAGE_PLAN_SHA
            and stage["sourceRoot"] == W3_SOURCE_ROOT and stage["appDerived"] == W3_APP_DERIVED
            and stage["uiDerived"] == str(Path(root_admission["buildRoot"]) / "ui-derived")
            and stage["sourceManifestSHA256"] == MANIFEST
            and stage["canonicalSDKRevision"] == W3_SDK_REVISION and stage["sdkReceiptSHA256"] == SDK_RECEIPT
            and stage["originalIntermediatesAndPackagePathsReused"] is True
            and stage["applicationBuilds"] == stage["nativeBuilds"] == stage["tests"] == 0,
            "Actual warm stage source, SDK, preservation or no-build evidence differs")
    require(plan["schema"] == "pinkha-root-warm-retry-staging-plan-v1" and plan["readyForStaging"] is True
            and plan["appSourceSHA"] == W3_SOURCE and plan["appSourceTree"] == W3_TREE
            and plan["previousSourceSHA"] == W3_PREVIOUS
            and plan["sourceRoot"] == W3_SOURCE_ROOT and plan["appDerived"] == W3_APP_DERIVED
            and plan["buildRoot"] == root_admission["buildRoot"] != W3_FAILED_ROOT
            and plan["nativeMaterializationRoot"] == root_admission["nativeMaterializationRoot"]
            and plan["pins"]["sdkMaterializerSHA256"] == W3_SDK_HELPER_SHA
            and plan["pins"]["hanlinSourcePinSHA256"] == W3_SDK_SOURCE_SHA,
            "Actual root-authorized warm forward plan differs")
    w3_stage_control_references(plan, contract, gate)
    original_stage_admission, resource_reassessment = w3_resource512_restore_admission(
        root_admission, contract, adapter, warm)
    template = gate.json_ref(plan["buildAdmissionTemplate"])
    require(template["readyForBuild"] is False
            and all(original_stage_admission.get(key) == value for key, value in template.items()
                    if key not in {"readyForBuild", "sourceStaging", "cacheQualification"}),
            "Reviewed staging template differs from the final root-approved admission")
    require(sha(pinned(contract["ownedLifecycle"])) == W3_LIFECYCLE_SHA
            and plan["ownedLifecycleHelper"]["sha256"] == W3_LIFECYCLE_SHA,
            "Original owned process lifecycle helper changed")
    gate.read_ref(plan["ownedLifecycleHelper"])
    owners = contract["stageOwners"]
    require(set(owners) == {"before", "after"}, "Both actual staging ownership observations required")
    for reference in owners.values():
        value = decode(pinned(reference))
        require(value["scopedCompilerOrQueueProcesses"] == [] and value["databasePresent"] is True,
                "Warm staging did not observe the unowned existing compiler database")

    preservation_raw = pinned(contract["preservationReceipt"])
    require(sha(preservation_raw) == APP16_PRESERVATION == stage["originalPreservationSHA256"]
            and w3_ref(contract["preservationReceipt"]) == root_admission["originalRetention"]
            and plan["originalPreservationReceipt"] == contract["preservationReceipt"]["path"],
            "Historical original-preservation receipt differs")
    original = decode(preservation_raw)
    require(original["status"] == "PASS_ORIGINAL_SOURCE_AND_PRODUCTS_BYTES_MODES_LINKS"
            and original["originalProducerSHA256"] == BUILD15_PROOF["receipt"]
            and original["source"] == W3_SOURCE_ROOT, "Original App15 preservation identity differs")
    original_root = Path(contract["preservationReceipt"]["path"]).parent
    copies = [(Path(original["retainedSource"]), original_root / "original-source-inventory.json", original["sourceInventorySHA256"])]
    copies.extend((Path(value["retained"]), original_root / (name + "-original-inventory.json"), value["inventorySHA256"])
                  for name, value in original["products"].items())
    retained = []
    for path, inventory_path, expected in copies:
        rows = gate.json_ref({"path": str(inventory_path), "sha256": expected})
        require(stage_control.inventory(gate.canonical(path, directory=True)) == rows,
                "Retained original source/products bytes, modes or links changed")
        retained.append({"root": str(path), "inventory": str(inventory_path), "inventorySHA256": expected, "entries": len(rows)})
    reverified_raw = pinned(contract["preservationRevalidation"])
    reverified = decode(reverified_raw)
    require(sha(reverified_raw) == stage["originalPreservationReverifiedSHA256"]
            == "9537b4c6c749945f9061b77fd5dfdb98188ce3969fc04417ed11fb5586caaece"
            and w3_ref(contract["preservationRevalidation"]) == plan["original15PriorReverification"]
            and reverified == {"status": "PASS_RETAINED_ORIGINAL_SOURCE_AND_PRODUCTS_REVERIFIED",
                 "receiptSHA256": APP16_PRESERVATION, "inventories": retained, "currentAppProductsEqualOriginal": True},
            "The retained historical pre-first-build App15 revalidation differs")
    failed = w3_failed_preservation(contract, stage, plan, gate, preserve, adapter)

    # Qualify the same warm paths/packages; no reset, package resolution or build.
    cache_raw = pinned(contract["cacheQualification"])
    cache = decode(cache_raw)
    require(sha(cache_raw) == APP16_CACHE_QUALIFICATION == receipt["inputs"]["cacheRequalificationReceiptSHA256"]
            and w3_ref(contract["stagingReceipt"]) == root_admission["sourceStaging"]
            and w3_ref(contract["cacheQualification"]) == root_admission["cacheQualification"],
            "Actual warm stage/cache pins differ from the producer admission")
    warm.WAVE3_ADMISSION, warm.EXPECTED = root_admission, W3_SOURCE
    warm.SOURCE, warm.APP_DERIVED = Path(W3_SOURCE_ROOT), Path(W3_APP_DERIVED)
    warm.sha, warm.PHASE_GROWTH, warm.FLOOR = warm.wr_sha, {"app": 6442450944}, 2147483648
    warm.CONCURRENT_GROWTH = root_admission["warmRetry"]["concurrentGrowthAllowanceBytes"]
    warm.wr_validate_cache(cache, stage)
    package_before = decode(pinned(warm_refs["packagesBefore"]))
    package_after = decode(pinned(warm_refs["packagesAfter"]))
    require(package_before == package_after == cache["packageState"]
            and package_after["packageResolvedSHA256"] == root_admission["pins"]["packageResolvedSHA256"]
            and len(package_after["checkouts"]) == 56 and len(package_after["localSDKPackages"]) == 4,
            "Complete actual warm package custody differs before/after staging")
    require(set(cache["observedSizes"]) == set(cache["observedPaths"])
            and all(type(value) is int and value > 0 for value in cache["observedSizes"].values()),
            "Actual positive warm directory measurements are required")
    ui_before = decode(pinned(warm_refs["uiCacheBefore"]))
    ui_original = str(Path(W3_FAILED_ROOT) / "ui-derived")
    require(plan["uiDerivedCloneSource"] == ui_before["root"] == ui_original
            and preserve.inventory(gate.canonical(ui_original, directory=True)) == ui_before["entries"]
            and stage["uiCacheClone"]["method"] == "Darwin clonefile(flags=0), no regular-file copy fallback",
            "Original never-invoked UI cache custody or actual APFS clone evidence differs")
    return {"stageReceiptSHA256": sha(stage_raw), "stagePlanSHA256": sha(plan_raw),
            "priorApp15PreservationSHA256": APP16_PRESERVATION,
            "preservationRevalidationSHA256": sha(reverified_raw), "cacheRequalificationSHA256": sha(cache_raw),
            "originalStageCacheReuseClaimAccepted": True, "retainedOriginalInventories": retained,
            "warmPackageCheckouts": 56, "localSDKPackages": 4, "actualWarmCacheRequalified": True,
            "resourceReassessment": resource_reassessment, **failed}



def w3_phase_proofs(contract, receipt):
    phases = contract["phaseReceipts"]
    require(set(phases) == {"app", "ui"}, "Both original App/UI process outcomes required")
    for phase in ("app", "ui"):
        pins = phases[phase]
        require(set(pins) == {"result", "processExit"}, "Closed original phase pin set required")
        result, exited = decode(pinned(pins["result"])), decode(pinned(pins["processExit"]))
        require(result == receipt[phase] and all(result.get(key) == value for key, value in exited.items())
                and result["phase"] == exited["phase"] == phase
                and result["sourceCommit"] == exited["sourceCommit"] == W3_SOURCE
                and result["status"] == exited["status"] == "PASS_BUILD_EXIT_0"
                and result["exitCode"] == exited["exitCode"] == 0
                and result["cleanupErrors"] == result["termination"] == []
                and result["ownedProcessGroup"] == "ABSENT_ESRCH"
                and result["processExitReceiptSHA256"] == pins["processExit"]["sha256"]
                and "build-for-testing" in result["argv"]
                and all(any("-D " + flag in token for token in result["argv"]) for flag in FLAGS),
                "Original source/flags/exit/owned-process proof is incomplete")


def w3_native_sdk_proofs(admission, receipt, root_admission, source, gate, stage_control):
    contract = admission["app16Producer"]
